package com.comandos.transfer.model;
import com.comandos.core.model.CoreEntity;import com.comandos.inventory.model.*;import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="erp_inventory_transfer_item") public class InventoryTransferItem extends CoreEntity {
 @ManyToOne(optional=false)@JoinColumn(name="transfer_id",nullable=false)public InventoryTransfer transfer;@ManyToOne(optional=false)@JoinColumn(name="model_id",nullable=false)public ItemModel model;@ManyToOne@JoinColumn(name="asset_id")public AssetItem asset;@ManyToOne@JoinColumn(name="lot_id")public StockLot lot;@ManyToOne@JoinColumn(name="source_balance_id")public StockBalance sourceBalance;@ManyToOne@JoinColumn(name="destination_balance_id")public StockBalance destinationBalance;@ManyToOne(optional=false)@JoinColumn(name="source_location_id",nullable=false)public StockLocation sourceLocation;@ManyToOne(optional=false)@JoinColumn(name="destination_location_id",nullable=false)public StockLocation destinationLocation;@OneToOne(optional=false)@JoinColumn(name="out_movement_id",nullable=false,unique=true)public StockMovement outMovement;@OneToOne(optional=false)@JoinColumn(name="in_movement_id",nullable=false,unique=true)public StockMovement inMovement;
 @Column(nullable=false)public String modelName;@Column(nullable=false)public String sku;@Column(nullable=false)public String stockCode;@Column(nullable=false)public String sourceLocationName;@Column(nullable=false)public String destinationLocationName;@Column(nullable=false)public String unitOfMeasure;@Column(nullable=false,precision=19,scale=4)public BigDecimal quantity;
}
